<script lang="ts">
import PluginActions from './plugins/PluginActions.vue'
import { t } from './i18n'
import { computed, defineComponent, onMounted, ref, unref, watch, type PropType } from 'vue'
import { formatChord } from './settings/shortcuts'
import { renderTemplate } from './documents/personalItems'
import CodeEditor from './CodeEditor.vue'
import type { Doc } from './workspace/sample'
import TabBar from './TabBar.vue'
import MenuBar from './MenuBar.vue'
import StatusBar from './StatusBar.vue'
import FormatIcon from './editor/FormatIcon'
import { ChevronDown } from 'lucide-vue-next'

export default defineComponent({
  name: 'EditorWorkspace',
  components: { PluginActions, FormatIcon, CodeEditor, TabBar, MenuBar, StatusBar, ChevronDown },
  props: { context: { type: Object as PropType<Record<string, any>>, required: true } },
  setup(props) {
    const editingBody = ref<HTMLElement>()
    const previewShare = ref(.5)
    function updatePreviewShare() {
      if (!unref(props.context.previewWidthCustomized)) { previewShare.value = .5; return }
      const width = editingBody.value?.clientWidth
      if (width) previewShare.value = Math.max(.1, Math.min(.9, Number(unref(props.context.previewWidth)) / width))
    }
    onMounted(updatePreviewShare)
    watch(() => [unref(props.context.previewWidth), unref(props.context.previewWidthCustomized)], updatePreviewShare, { flush: 'sync' })
    const previewStyle = computed(() => ({ width: `${previewShare.value * 100}%` }))
    const htmlActive = computed(() => /\.html?$/i.test(unref(props.context.activeDoc)?.path || ''))
    const linkFiles = computed(() => ((unref(props.context.docs) || []) as Doc[]).flatMap(item => item.relativePath ? [item.relativePath] : []))
    const snippetMenuItems = computed(() => {
      if (!unref(props.context.showInlineSnippetMenu)) return []
      const filename = unref(props.context.activeDoc)?.path?.split('/').pop() || '未命名文件.md'
      const now = new Date()
      return (unref(props.context.snippets) || []).map((item: { id: string; name: string; content: string }) => ({ ...item, name: renderTemplate(item.name, filename, now) }))
    })
    const shortcutIds: Record<string, string> = { 'inline-formula': 'inlineFormula', mermaid: 'insertMermaid', mindmap: 'insertMindmap', 'image-url': 'imageUrl', 'format-document': 'formatDocument', code: 'inlineCode', 'code-block': 'codeBlock', p: 'heading0', list: 'unorderedList', 'ordered-list': 'orderedList', 'task-list': 'taskList', hr: 'horizontalRule', 'image-local': 'image', 'hide-toolbar': 'toggleToolbar', ...Object.fromEntries(['tip', 'note', 'important', 'warning', 'caution'].map(kind => [`callout-${kind}`, `callout${kind[0].toUpperCase()}${kind.slice(1)}`])) }
    const shortcutLabel = (id: string) => formatChord(props.context.assignedChord?.(shortcutIds[id] || id) || '')
    const toolbarTitle = (label: string, id: string) => { label = t(label); const shortcut = shortcutLabel(id); return shortcut ? `${label}（${shortcut}）` : label }
    return Object.assign({}, props.context, { snippetMenuItems, linkFiles, shortcutLabel, toolbarTitle, htmlActive, editingBody, previewStyle, previewShare })
  }
})
</script>

<template>
<section class="editing-workspace">
        <div class="editor-topbar" data-tauri-drag-region="deep">
          <TabBar :context="workspaceUiContext"/>
          <span class="topbar-drag" data-tauri-drag-region="deep"/>
          <MenuBar area="editorTop" :context="workspaceUiContext"/>
        </div>
        <div ref="editingBody" class="editing-body" :style="{ '--preview-toolbar-center': `${previewShare * 50}%` }"><div v-if="toolbarEnabled && mode === 'wysiwyg' && editorFocused" class="editor-toolbar floating-toolbar" @mousedown="onToolbarMouseDown"><div class="format-group"><div class="block-style-wrap"><button class="block-style-trigger" :title="$t('段落样式')" :aria-expanded="showBlockMenu" @click="showBlockMenu = !showBlockMenu">{{ $t(selectedBlockLabel) }} <ChevronDown :size="13"/></button><div v-if="showBlockMenu" class="block-style-menu"><button v-for="level in 6" :key="level" :class="{ selected: selectedBlock === `h${level}` }" @click="applyBlockStyle(`h${level}`)"><FormatIcon :name="`h${level}`"/><span>{{ ['一','二','三','四','五','六'][level - 1] }}{{ $t('级标题') }}</span><kbd v-if="shortcutLabel(`heading${level}`)">{{ shortcutLabel(`heading${level}`) }}</kbd></button><div class="block-menu-separator"/><button :class="{ selected: selectedBlock === 'p' }" @click="applyBlockStyle('p')"><FormatIcon name="paragraph"/><span>{{ $t('段落') }}</span><kbd v-if="shortcutLabel('p')">{{ shortcutLabel('p') }}</kbd></button><button @click="applyBlockStyle('frontmatter')"><FormatIcon name="frontmatter"/><span>Front matter</span><kbd v-if="shortcutLabel('frontmatter')">{{ shortcutLabel('frontmatter') }}</kbd></button><div class="block-menu-separator"/><button :class="{ selected: selectedBlock === 'table' }" @click="applyBlockStyle('table')"><FormatIcon name="table"/><span>{{ $t('表格') }}</span><kbd v-if="shortcutLabel('table')">{{ shortcutLabel('table') }}</kbd></button><button :class="{ selected: selectedBlock === 'code-block' }" @click="applyBlockStyle('code')"><FormatIcon name="code"/><span>{{ $t('代码块') }}</span><kbd v-if="shortcutLabel('code-block')">{{ shortcutLabel('code-block') }}</kbd></button><button :class="{ selected: selectedBlock === 'mermaid' }" @click="applyBlockStyle('mermaid')"><FormatIcon name="mermaid"/><span>{{ $t('流程图') }}</span><kbd v-if="shortcutLabel('mermaid')">{{ shortcutLabel('mermaid') }}</kbd></button><button @click="applyBlockStyle('mindmap')"><FormatIcon name="mindmap"/><span>{{ $t('脑图') }}</span><kbd v-if="shortcutLabel('mindmap')">{{ shortcutLabel('mindmap') }}</kbd></button><button :class="{ selected: selectedBlock === 'formula' }" @click="applyBlockStyle('formula')"><FormatIcon name="formula"/><span>{{ $t('公式块') }}</span><kbd v-if="shortcutLabel('formula')">{{ shortcutLabel('formula') }}</kbd></button><button :class="{ selected: selectedBlock === 'footnote' }" @click="applyBlockStyle('footnote')"><FormatIcon name="footnote"/><span>{{ $t('脚注') }}</span><kbd v-if="shortcutLabel('footnote')">{{ shortcutLabel('footnote') }}</kbd></button><button @click="format('comment'); showBlockMenu = false"><FormatIcon name="comment"/><span>{{ $t('注释') }}</span><kbd v-if="shortcutLabel('comment')">{{ shortcutLabel('comment') }}</kbd></button><button :class="{ selected: selectedBlock === 'hr' }" @click="applyBlockStyle('hr')"><FormatIcon name="hr"/><span>{{ $t('水平分割线') }}</span><kbd v-if="shortcutLabel('hr')">{{ shortcutLabel('hr') }}</kbd></button></div></div><span class="tool-divider"/><button :title="toolbarTitle('粗体', 'bold')" :class="{ pressed: boldActive }" @click="format('bold')"><FormatIcon name="bold"/></button><button :title="toolbarTitle('斜体', 'italic')" :class="{ pressed: italicActive }" @click="format('italic')"><FormatIcon name="italic"/></button><span class="text-style-anchor"><button :title="$t('文字样式')" :aria-label="$t('文字样式')" aria-haspopup="menu" :aria-expanded="showTextStyleMenu" :class="{ pressed: ['strikethrough', 'underline', 'inline-formula'].some(id => activeFormatIds.includes(id)) }" @click="showTextStyleMenu = !showTextStyleMenu"><FormatIcon name="text-style"/></button><span v-if="showTextStyleMenu" class="list-style-menu text-style-menu" role="menu" :aria-label="$t('文字样式')"><button v-for="item in [{ id: 'strikethrough', label: '删除线' }, { id: 'underline', label: '下划线' }, { id: 'inline-formula', label: '行内公式' }]" :key="item.id" role="menuitemcheckbox" :aria-checked="activeFormatIds.includes(item.id)" :class="{ selected: activeFormatIds.includes(item.id) }" @click="format(item.id); showTextStyleMenu = false"><FormatIcon :name="item.id" :size="15"/>{{ $t(item.label) }}<kbd v-if="shortcutLabel(item.id)">{{ shortcutLabel(item.id) }}</kbd></button></span></span><button :title="toolbarTitle('行内代码', 'code')" :class="{ pressed: activeFormatIds.includes('code') }" :aria-pressed="activeFormatIds.includes('code')" @click="format('code')"><FormatIcon name="inline-code"/></button><button :title="toolbarTitle('超链接', 'link')" :class="{ pressed: activeFormatIds.includes('link') }" :aria-pressed="activeFormatIds.includes('link')" @click="format('link')"><FormatIcon name="link"/></button><span class="tool-divider"/><span class="image-insert-anchor"><button :title="$t('插入图片')" :aria-expanded="showImageMenu" @click="showImageMenu = !showImageMenu"><FormatIcon name="image"/></button><span v-if="showImageMenu" class="image-insert-menu"><button @click="showImageMenu = false; format('image-url')"><FormatIcon name="image" :size="15"/>{{ $t('图片链接') }}<kbd v-if="shortcutLabel('image-url')">{{ shortcutLabel('image-url') }}</kbd></button><button @click="showImageMenu = false; format('image-local')"><FormatIcon name="image-local" :size="15"/>{{ $t('本地图片') }}<kbd v-if="shortcutLabel('image-local')">{{ shortcutLabel('image-local') }}</kbd></button></span></span><span class="quote-style-anchor"><button :title="$t('引用与警告框')" :aria-label="$t('引用与警告框')" :class="{ pressed: selectedBlock === 'quote' || selectedBlock.startsWith('callout-') }" :aria-expanded="showQuoteMenu" @click="showQuoteMenu = !showQuoteMenu"><FormatIcon name="quote"/></button><span v-if="showQuoteMenu" class="quote-style-menu"><button :class="{ selected: selectedBlock === 'quote' }" @click="applyBlockStyle('quote'); showQuoteMenu = false"><FormatIcon name="quote"/><span class="quote-menu-label">{{ $t('普通引用') }}</span><kbd v-if="shortcutLabel('quote')">{{ shortcutLabel('quote') }}</kbd></button><div class="block-menu-separator"/><button v-for="item in [{ kind: 'tip', label: '提示' }, { kind: 'note', label: '备注' }, { kind: 'important', label: '重要' }, { kind: 'warning', label: '警告' }, { kind: 'caution', label: '注意' }]" :key="item.kind" :class="{ selected: selectedBlock === `callout-${item.kind}` }" @click="applyBlockStyle(`callout-${item.kind}`); showQuoteMenu = false"><FormatIcon :name="`callout-${item.kind}`"/><span class="quote-menu-label">{{ $t(item.label) }}</span><small>{{ item.kind.toUpperCase() }}</small><kbd v-if="shortcutLabel(`callout-${item.kind}`)">{{ shortcutLabel(`callout-${item.kind}`) }}</kbd></button></span></span><span class="list-style-anchor"><button :title="$t('列表')" :class="{ pressed: ['list', 'ordered-list', 'task-list'].includes(selectedBlock) }" :aria-expanded="showListMenu" @click="showListMenu = !showListMenu"><FormatIcon name="list"/></button><span v-if="showListMenu" class="list-style-menu"><button :class="{ selected: selectedBlock === 'list' }" @click="applyBlockStyle('list'); showListMenu = false"><FormatIcon name="list" :size="15"/> {{ $t('无序列表') }}<kbd v-if="shortcutLabel('list')">{{ shortcutLabel('list') }}</kbd></button><button :class="{ selected: selectedBlock === 'ordered-list' }" @click="applyBlockStyle('ordered-list'); showListMenu = false"><FormatIcon name="ordered-list" :size="15"/> {{ $t('有序列表') }}<kbd v-if="shortcutLabel('ordered-list')">{{ shortcutLabel('ordered-list') }}</kbd></button><button :class="{ selected: selectedBlock === 'task-list' }" @click="applyBlockStyle('task-list'); showListMenu = false"><FormatIcon name="task" :size="15"/> {{ $t('任务列表') }}<kbd v-if="shortcutLabel('task-list')">{{ shortcutLabel('task-list') }}</kbd></button></span></span><span class="snippet-anchor"><button :title="$t('插入片段')" :aria-expanded="showInlineSnippetMenu" @click="showInlineSnippetMenu = !showInlineSnippetMenu"><FormatIcon name="snippet"/></button><span v-if="showInlineSnippetMenu" class="snippet-menu"><button v-for="item in snippetMenuItems" :key="item.id" @mousedown.prevent @click="formattingEditor?.insertSnippet(item.content); showInlineSnippetMenu = false">{{ item.name }}</button><span v-if="!snippets.length">{{ $t('在设置中添加片段后，可从这里插入') }}</span></span></span><PluginActions location="format-toolbar"/><span class="block-actions-anchor"><button :title="$t('更多操作')" :aria-expanded="showBlockActions" @click="showBlockActions = !showBlockActions"><FormatIcon name="more" :size="18"/></button><span v-if="showBlockActions" class="block-actions-menu"><button @click="format('format-document'); showBlockActions = false"><FormatIcon name="format-document" :size="15"/> {{ $t('格式化') }}<kbd v-if="shortcutLabel('format-document')">{{ shortcutLabel('format-document') }}</kbd></button><div class="block-menu-separator"/><button @click="copyCurrentBlock('markdown')"><FormatIcon name="copy-markdown" :size="15"/> {{ $t('复制为 Markdown') }}</button><button @click="copyCurrentBlock('html')"><FormatIcon name="copy-html" :size="15"/> {{ $t('复制为 HTML') }}</button><button @click="copyCurrentBlock('image')"><FormatIcon name="copy-image" :size="15"/> {{ $t('复制为图片') }}</button><button @click="copyCurrentBlock('plain')"><FormatIcon name="copy-plain" :size="15"/> {{ $t('复制为纯文本') }}</button><div class="block-menu-separator"/><button @click="toolbarEnabled = false; showBlockActions = false"><FormatIcon name="hide-toolbar" :size="15"/> {{ $t('隐藏工具栏') }}<kbd v-if="shortcutLabel('hide-toolbar')">{{ shortcutLabel('hide-toolbar') }}</kbd></button></span></span></div></div>
        <section class="editor-pane"><Transition name="view-fade" mode="out-in"><div :data-editor-mode="mode" class="editor-scroll" :class="{ 'typewriter-mode': typewriter }"><CodeEditor v-if="!isTauri || activeDoc.loaded" :key="activeId" ref="editor" v-model="content" :typewriter="typewriter"  :focus-mode="focusMode" :read-only="readOnlyMode" :class="{ 'no-line-wrap': !wrapLines && mode !== 'split' && !htmlActive }" :doc-id="activeId" :file-kind="activeKind" :relative-path="activeDoc.relativePath" :link-files="linkFiles" :link-directories="workspaceDirectories" :workspace-root="currentWorkspaceRoot" @open-link="openFileLink" :attachment-directory="attachmentDirectory" :clipboard-directory="clipboardDirectory" :attachment-naming="attachmentNaming" :image-data="imageData" :image-widths="activeImageWidths" :layout-key="[fontSize,lineHeight,paragraphSpacing,tableWidth,editorFontFamily,indent].join(':')" :body-line-numbers="bodyLineNumbers" :code-block-line-numbers="codeBlockLineNumbers" :rich="markdownActive && mode === 'wysiwyg'" :diagram-visual-editing="diagramVisualEditing" @focus="editorFocused = true; activeEditingPane = 'source'" @blur="onEditorBlur" @fold-change="onHeadingFoldsChange" @selection="info => onEditorSelection(info, 'source')" @error="notify" @user-scroll="claimUserScroll('source')" @scroll="element => syncScroll('source', element)" /></div></Transition>
      </section>

      <div v-if="mode === 'split'" class="pane-resizer preview-resizer" role="separator" aria-orientation="vertical" :aria-label="$t('调整预览栏宽度')" @pointerdown="startResize('preview', $event)"/>
      <Transition name="preview-slide"><section v-if="mode === 'split'" class="preview-pane" :class="{ 'typewriter-mode': typewriter }" :style="previewStyle"><CodeEditor ref="previewEditor" v-model="content" class="split-rich-editor" :doc-id="`${activeId}:split-preview`" :file-kind="activeKind" :relative-path="activeDoc.relativePath" :link-files="linkFiles" :link-directories="workspaceDirectories" :workspace-root="currentWorkspaceRoot" @open-link="openFileLink" :attachment-directory="attachmentDirectory" :clipboard-directory="clipboardDirectory" :attachment-naming="attachmentNaming" :image-data="imageData" :image-widths="activeImageWidths" :layout-key="[fontSize,lineHeight,paragraphSpacing,tableWidth,editorFontFamily,indent].join(':')" :code-block-line-numbers="codeBlockLineNumbers" :rich="true" :show-block-controls="false" :keep-preview-rendered="true" :preview-only="true" :typewriter="typewriter" :focus-mode="focusMode" :read-only="true" @focus="editorFocused = true; activeEditingPane = 'preview'" @blur="onEditorBlur" @fold-change="onHeadingFoldsChange" @selection="info => onEditorSelection(info, 'preview')" @error="notify" @user-scroll="claimUserScroll('preview')" @scroll="onPreviewEditorScroll"/></section></Transition>
        </div>
        <StatusBar :context="workspaceUiContext"/>
      </section>
</template>
